// Grandparent Superclass
class Device {
    protected String brand;

    public Device(String brand) {
        this.brand = brand;
    }

    public void powerOn() {
        System.out.println(brand + " device is now powered ON.");
    }
}

// Intermediate Parent (Subclass of Device)
class Computer extends Device {
    protected int ramGB;

    public Computer(String brand, int ramGB) {
        super(brand);
        this.ramGB = ramGB;
    }

    public void runDiagnostics() {
        System.out.println("Running diagnostics on " + ramGB + " GB RAM system...");
    }
}

// Leaf Child (Subclass of Computer)
class Laptop extends Computer {
    private double weightKg;

    public Laptop(String brand, int ramGB, double weightKg) {
        super(brand, ramGB);
        this.weightKg = weightKg;
    }

    public void showPortability() {
        System.out.println(brand + " laptop weighs only " + weightKg + " kg (Easy to carry!)");
    }
}

public class MultilevelDemo {
    public static void main(String[] args) {
        // Instantiate the leaf class Laptop
        Laptop myLaptop = new Laptop("Dell", 16, 1.4);

        // 1. Invoking method from Grandparent (Device)
        myLaptop.powerOn();

        // 2. Invoking method from Parent (Computer)
        myLaptop.runDiagnostics();

        // 3. Invoking method from Child (Laptop)
        myLaptop.showPortability();
    }
}

