activities.code:
class Animal {
    protected String species = "Generic Animal";

    public void breathe() {
        System.out.println("Inhaling oxygen...");
    }
}

class Mammal extends Animal {
    protected boolean warmBlooded = true;

    public void feedMilk() {
        System.out.println("Mammal feeding milk to offspring.");
    }
}

class Dog extends Mammal {
    protected String breed;

    public Dog(String breed) {
        this.species = "Canine";
        this.breed = breed;
    }

    public void bark() {
        System.out.println(breed + " barks: Woof woof!");
    }
}

public class BiologyDemo {
    public static void main(String[] args) {
        Dog retriever = new Dog("Golden Retriever");

        // All three levels working together:
        retriever.breathe();   // From Grandparent Animal
        retriever.feedMilk();  // From Parent Mammal
        retriever.bark();      // From Child Dog

        System.out.println("Species: " + retriever.species);
        System.out.println("Warm blooded: " + retriever.warmBlooded);
    }
}

