class Vehicle {
    String model;

    void startEngine() {
        System.out.println(model + " engine started.");
    }
}

class FourWheeler extends Vehicle {
    int wheelCount = 4;

    void checkTires() {
        System.out.println("Inspecting " + wheelCount + " wheels.");
    }
}

class Sedan extends FourWheeler {
    int trunkCapacityLiters;

    void openTrunk() {
        System.out.println("Opening trunk of " + trunkCapacityLiters + " liters.");
    }
}

public class Main {
    public static void main(String[] args) {
        Sedan s = new Sedan();
        s.model = "Camry";
        s.trunkCapacityLiters = 450;
        s.startEngine();
        s.checkTires();
        s.openTrunk();
    }
}

