class Entity {
    protected String name;
    protected int health;

    public Entity(String name, int health) {
        this.name = name;
        this.health = health;
    }
}

class Hero extends Entity {
    protected int mana;

    public Hero(String name, int health, int mana) {
        super(name, health);
        this.mana = mana;
    }

    public void castSpell(int cost) {
        mana -= cost;
        System.out.println(name + " cast spell! Mana left: " + mana);
    }
}

class Paladin extends Hero {
    protected int armor;

    public Paladin(String name, int health, int mana, int armor) {
        super(name, health, mana);
        this.armor = armor;
    }

    public void holyShield() {
        System.out.println(name + " deployed Holy Shield! Armor: " + armor + ", Health: " + health);
    }
}

public class Main {
    public static void main(String[] args) {
        Paladin p = new Paladin("Arthur", 150, 60, 40);
        p.castSpell(20);
        p.holyShield();
    }
}
